83	 * with ENAMETOOLONG from 248 characters (247 still works), while `mkdir` and starting the CLI there
84	 * still work up to the 258-character working-directory limit (#102,
85	 * docs/qa/2026-10-19-wp-f5-launch-diagnosis.md). A name that already exists is never reused or
86	 * removed; a few fresh names are tried instead.
87	 */
88	async function probeDirectory(): Promise<string> {
89	  for (let attempt = 1; ; attempt += 1) {
90	    const directory = join(tmpdir(), `gg-claude-probe-${randomBytes(4).toString('hex')}`);
91	    try {
92	      await mkdir(directory, { mode: 0o700 });
93	      return directory;
94	    } catch (error) {
95	      if (
96	        (error as NodeJS.ErrnoException).code !== 'EEXIST' ||
97	        attempt === PROBE_DIRECTORY_ATTEMPTS
98	      )
99	        throw error;
100	    }
101	  }
102	}
103	/** Windows starts no process in a working directory longer than this (#102, #364). */
104	const WINDOWS_WORKING_DIRECTORY_LIMIT = 258;
105	/**
106	 * A check whose process the runner established as refused at start or whose output was lost
107	 * (#364). It is not an option failure, so the help check keeps its fixed detail. Module-private:
108	 * callers see an ordinary `HARNESS_TURN_FAILED` with the same message and retriability.
109	 */
110	class CheckProcessFailure extends ClaudeHarnessError {
111	  constructor(message: string) {
112	    super('HARNESS_TURN_FAILED', message);
113	  }
114	}
115	/**
116	 * A refused start, worded from what the runner established (#364). A spawn `ENOENT` alone does not
117	 * say whether the executable or the working directory failed, so only an established absence is
118	 * reported as a missing CLI, and only the turn's own working directory is configuration; the
119	 * temporary check folder is not. Otherwise the cause stays unknown: the message names both
120	 * operands, or the Windows limit as a fact about the path's length. Messages are fixed text.
121	 */
122	function startFailure(
123	  code: NonNullable<ClaudeProcessResult['spawnCode']>,
124	  refusal: ClaudeStartRefusal | undefined,
125	  cwd: string,
126	  probe: boolean,
127	): ClaudeHarnessError {
128	  if (refusal === 'executable-missing')
129	    return new ClaudeHarnessError(
130	      'HARNESS_NOT_INSTALLED',
131	      probe
132	        ? 'Claude CLI was not found at the configured path.'
133	        : 'The Claude executable was not found at its configured path; install the Claude CLI or correct its path',
134	    );
135	  if (refusal) {
136	    const state = refusal === 'working-directory-missing' ? 'does not exist' : 'is not a folder';
137	    return probe
138	      ? new CheckProcessFailure(
139	          `Claude CLI could not be started because its temporary check folder ${state}.`,
140	        )
141	      : new ClaudeHarnessError(
142	          'HARNESS_INVALID_CONFIGURATION',
143	          `Claude could not be started because the working directory ${state}; check the working directory setting`,
144	        );
145	  }
146	  const limit = WINDOWS_WORKING_DIRECTORY_LIMIT;
147	  const long = resolve(cwd).length > limit;
148	  if (probe)
149	    return new CheckProcessFailure(
150	      long
151	        ? `Claude CLI could not be started (${code}) from its temporary check folder, whose path (from TEMP or TMP) is longer than the ${limit} characters Windows allows for a working directory.`
152	        : `Claude CLI could not be started (${code}).`,
153	    );
154	  return new ClaudeHarnessError(
155	    'HARNESS_TURN_FAILED',
156	    long
157	      ? `Claude could not be started (${code}); the working directory path is longer than the ${limit} characters Windows allows`
158	      : `Claude could not be started (${code}); check the Claude executable's path and permissions and the working directory`,
159	  );
160	}
161	/**
162	 * Turns and no-turn probes share the failure order. A probe's messages are single detail
163	 * sentences about the check (preflight adds the one next step).
164	 */
165	function checkOutcome(
166	  result: ClaudeProcessResult,
167	  signal: AbortSignal,
168	  cwd: string,
169	  probe = false,
170	): void {
171	  if (result.terminationUnconfirmed)
172	    throw new ClaudeHarnessError(
173	      'HARNESS_TERMINATION_UNCONFIRMED',
174	      probe
175	        ? 'Claude CLI check process did not confirm that it stopped.'
176	        : 'Claude process termination was not confirmed; stop the installed CLI before retrying',
177	    );
178	  if (signal.aborted || result.aborted) throw abortError();
179	  if (result.spawnCode) throw startFailure(result.spawnCode, result.startRefusal, cwd, probe);
180	  if (result.timedOut)
181	    throw new ClaudeHarnessError(
182	      'HARNESS_TIMEOUT',
183	      probe ? 'Claude CLI did not answer before the check deadline.' : 'Claude process timed out',
184	      true,
185	    );
186	  if (result.overflow)
187	    throw new ClaudeHarnessError(
188	      'HARNESS_OUTPUT_LIMIT',
189	      probe
190	        ? 'Claude CLI printed more output than the check accepts.'
191	        : 'Claude process output exceeded the configured limit',
192	    );
193	  if (result.callbackError) throw result.callbackError;
194	  // Lost check output is incomplete evidence: no state is inferred from its stdout or stderr.
195	  if (probe && result.outputFailed)
196	    throw new CheckProcessFailure('Claude CLI check output could not be read.');
197	  if (probe && result.exitCode !== 0 && result.failureState && result.failureState !== 'unknown') {
198	    const codes: Partial<
199	      Record<HarnessReadinessState, ConstructorParameters<typeof ClaudeHarnessError>[0]>
200	    > = {
201	      auth: 'HARNESS_NOT_AUTHENTICATED',
202	      quota: 'HARNESS_QUOTA_EXHAUSTED',
203	      transport: 'HARNESS_TRANSPORT_FAILED',
204	      'cli-incompatible': 'HARNESS_CLI_INCOMPATIBLE',
205	    };
206	    throw new ClaudeHarnessError(
207	      codes[result.failureState] ?? 'HARNESS_TURN_FAILED',
208	      readinessDetail('claude', result.failureState),
209	      result.failureState === 'transport',
210	    );
211	  }
212	  if (probe && (result.stdinFailed || result.exitCode !== 0))
213	    throw new ClaudeHarnessError(
214	      'HARNESS_TURN_FAILED',
215	      result.exitCode === null
216	        ? 'Claude CLI check stopped without an exit code.'
217	        : `Claude CLI check exited with code ${result.exitCode}.`,
218	    );
219	  if (result.stdinFailed || result.outputFailed || result.exitCode !== 0)
220	    throw new ClaudeHarnessError('HARNESS_TURN_FAILED', 'Claude turn failed');
221	}
222	/** Structural current HarnessPort implementation; additive HarnessId integration follows the issue 98 cutover. */
223	export class ClaudeHarness implements HarnessPort {
224	  readonly id = 'claude' as const;
225	  private readonly binary: string;
226	  private readonly runner: ClaudeCliRunner;
227	  private readonly platform: NodeJS.Platform;
228	  private readonly environment: NodeJS.ProcessEnv;
229	  constructor(private readonly options: ClaudeHarnessOptions = {}) {
230	    this.binary =
231	      options.binary ??
232	      join(
233	        options.env?.USERPROFILE ?? process.env.USERPROFILE ?? homedir(),
234	        '.local',
235	        'bin',
236	        'claude.exe',
237	      );
238	    this.runner = options.runner ?? runClaudeProcess;
239	    this.platform = options.platform ?? process.platform;
240	    this.environment = subscriptionEnvironment(options.env ?? process.env);
241	    for (const value of [options.preflightTimeoutMs, options.maxOutputBytes])
242	      if (value !== undefined && (!Number.isSafeInteger(value) || value <= 0))
243	        throw new ClaudeHarnessError(
244	          'HARNESS_INVALID_CONFIGURATION',
245	          'Claude process bounds must be positive integers',
246	        );
247	  }
248	  private supportedPolicies(): ClaudePolicy[] {
249	    return (['read-only', 'danger-full-access'] as const).map((sandbox) =>
250	      claudePolicy({ sandbox, approval: 'never' }, undefined, this.platform),
251	    );
252	  }
253	  private async inspect(signal: AbortSignal): Promise<{
254	    facts: ClaudeHarnessPreflight;
255	    failures: unknown[];
256	  }> {
257	    const facts: ClaudeHarnessPreflight = {
258	      state: 'unknown',
259	      ok: false,
260	      problems: [],
261	      authMethod: null,
262	      models: claudeModelCapabilities(),
263	      supportedPolicies: [],
264	    };
265	    const failures: unknown[] = [];
266	    // Unsupported platforms cannot execute this native Windows adapter.
267	    facts.supportedPolicies = this.supportedPolicies();
268	    const cwd = await probeDirectory();
269	    const run = async (args: string[], authStatus = false): Promise<string> => {
270	      if (signal.aborted) throw abortError();
271	      const result = await this.runner({
272	        binary: this.binary,
273	        args,
274	        cwd,
275	        env: this.environment,
276	        signal,
277	        timeoutMs: this.options.preflightTimeoutMs ?? 15000,
278	        maxOutputBytes: 128 * 1024,
279	        classifyDiagnostics: true,
280	      });
281	      // Auth status can confirm sign-out in JSON or text, even on exit 0. Interpret it only here;
282	      // timeout/start/termination failures remain authoritative and turn output is never inferred.
283	      let auth: unknown;
284	      if (authStatus) {
285	        try {
286	          auth = JSON.parse(result.stdout);
287	        } catch {
288	          /* No structured status. */
289	        }
290	      }
291	      let signOutDetail: string | undefined;
292	      if (
293	        typeof auth === 'object' &&
294	        auth !== null &&
295	        (('loggedIn' in auth && auth.loggedIn === false) ||
296	          ('authMethod' in auth &&
297	            typeof auth.authMethod === 'string' &&
298	            auth.authMethod !== '' &&
299	            auth.authMethod !== 'claude.ai'))
300	      ) {
301	        signOutDetail =
302	          'loggedIn' in auth && auth.loggedIn === false
303	            ? 'Claude is not signed in.'
304	            : 'Claude is not signed in with a Claude.ai account.';
305	      }
306	      if (
307	        authStatus &&
308	        (signOutDetail || /\bnot logged in\b/i.test(result.stdout) || result.notLoggedIn)
309	      ) {
310	        checkOutcome({ ...result, exitCode: 0 }, signal, cwd, true);
311	        facts.authenticated = false;
312	        throw new ClaudeHarnessError(
313	          'HARNESS_NOT_AUTHENTICATED',
314	          signOutDetail ?? 'Claude is not signed in.',
315	        );
316	      }
317	      // This path runs version/help/auth only; stdout cannot be a model response.
318	      // Recognised stderr is the CLI's primary error evidence, including conflicts with stdout.
319	      // An unrelated warning must not hide a recognised stdout failure. Turn stdout is untouched.
320	      checkOutcome(
321	        {
322	          ...result,
323	          failureState:
324	            !result.failureState || result.failureState === 'unknown'
325	              ? cliFailureState(result.stdout)
326	              : result.failureState,
327	        },
328	        signal,
329	        cwd,
330	        true,
331	      );
332	      return result.stdout;
333	    };
334	    try {
335	      const versionText = await run([...SUPPRESSION_ARGS, '--version']);
336	      const version = installedClaudeVersion(versionText);
337	      if (version !== undefined) facts.version = version;
338	      // --max-turns is a hidden CLI option. Parse it alongside --help without starting a turn.
339	      let help: string;
340	      try {
341	        help = await run([...SUPPRESSION_ARGS, '--max-turns', '1', '--help']);
342	      } catch (error) {
343	        // A rejected or failing option check names the version; timeouts and causes keep their
344	        // detail, as do a refused start and lost output, which say nothing about the options.
345	        if (
346	          error instanceof ClaudeHarnessError &&
347	          !(error instanceof CheckProcessFailure) &&
348	          (error.code === 'HARNESS_CLI_INCOMPATIBLE' || error.code === 'HARNESS_TURN_FAILED')
349	        )
350	          throw new ClaudeHarnessError(
351	            error.code,
352	            `Claude CLI ${version ?? '(unknown version)'} failed the --max-turns/--help check.`,
353	            error.retriable,
354	          );
355	        throw error;
356	      }
357	      verifyInstalledCapabilities(versionText, help);
358	    } catch (error) {
359	      failures.push(error);
360	    }
361	    // Login is a separate fact, even when the CLI version or policy flags are unsupported.
362	    try {
363	      const auth = await run([...SUPPRESSION_ARGS, 'auth', 'status', '--json'], true);
364	      facts.authMethod = authCategory(auth);
365	      if (facts.authMethod === null)
366	        throw new ClaudeHarnessError('HARNESS_TURN_FAILED', readinessDetail('claude', 'unknown'));
367	      facts.authenticated = true;
368	    } catch (error) {
369	      if (failureState(error) === 'auth') facts.authenticated = false;
370	      failures.push(error);
371	    }
372	    try {
373	      await rm(cwd, { recursive: true, force: true });
374	    } catch {
375	      // Cleanup must not hide a still-running native process or another prerequisite failure.
376	      if (!failures.length)
377	        failures.push(
378	          new ClaudeHarnessError(
379	            'HARNESS_TURN_FAILED',
380	            'Claude readiness check could not remove its temporary folder.',
381	          ),
382	        );
383	    }
384	    facts.ok = failures.length === 0;
385	    facts.state = facts.ok ? 'ready' : failureState(failures[0]);
386	    // One problem per failure: its own detail sentence and the action for its state.
387	    // Anything other than a typed harness error keeps the generic detail, never its message.
388	    facts.problems = [
389	      ...new Set(
390	        failures.map((error) =>
391	          readinessMessage(
392	            'claude',
393	            failureState(error),
394	            error instanceof ClaudeHarnessError ? error.message : undefined,
395	          ),
396	        ),
397	      ),
398	    ];
399	    return { facts, failures };
400	  }
401	  async preflight(): Promise<ClaudeHarnessPreflight> {
402	    try {
403	      return (await this.inspect(new AbortController().signal)).facts;
404	    } catch (error) {
405	      return {
406	        ...readinessFailure('claude', failureState(error)),
407	        authMethod: null,
408	        models: claudeModelCapabilities(),
409	        supportedPolicies: this.platform === 'win32' ? this.supportedPolicies() : [],
410	      };
411	    }
412	  }
413	  start(request: HarnessStartRequest, signal: AbortSignal): HarnessSession {
414	    return this.turn(request, signal);
415	  }
416	  resume(sessionId: string, request: HarnessStartRequest, signal: AbortSignal): HarnessSession {
417	    return this.turn(request, signal, sessionId);
418	  }
419	  private turn(
420	    request: HarnessStartRequest,
421	    signal: AbortSignal,
422	    resumeId?: string,
423	  ): HarnessSession {
424	    const controller = new AbortController();
425	    const abort = () => controller.abort();
426	    if (signal.aborted) abort();
427	    else signal.addEventListener('abort', abort, { once: true });
428	    const queue = new EventQueue<HarnessEvent>();
429	    let closed = false;
430	    let resolveId!: (id: string) => void, rejectId!: (error: unknown) => void;
431	    const sessionId = new Promise<string>((resolve, reject) => {
432	      resolveId = resolve;
433	      rejectId = reject;
434	    });
435	    sessionId.catch(() => undefined);
436	    const pump = async (): Promise<HarnessResult> => {
437	      let detectedVersion: string | undefined;
438	      let delivery: PromptSubmission = 'definitely-not-submitted';
439	      let accepted = false;
440	      let initialized = false;
441	      try {
442	        if (controller.signal.aborted) throw abortError();
443	        if (resumeId !== undefined && !validClaudeSessionId(resumeId))
444	          throw new ClaudeHarnessError(
445	            'HARNESS_INVALID_CONFIGURATION',
446	            'Claude resume requires a valid native session id',
447	          );
448	        const policy = claudePolicy(request.options, request.capabilities, this.platform);
449	        const settings = resolvedClaudeSettings(request);
450	        const inspection = await this.inspect(controller.signal);
451	        if (!inspection.facts.ok) throw inspection.failures[0];
452	        detectedVersion = inspection.facts.version;
453	        const accumulator = new ClaudeAccumulator({
454	          policy,
455	          model: settings.model,
456	          effort: settings.effort,
457	          mode: resumeId ? 'resumed' : 'fresh',
458	          ...(resumeId ? { resumeId } : {}),
459	          ...(request.turn.outputSchema ? { schema: request.turn.outputSchema } : {}),
460	        });
461	        const parser = new JsonLines();
462	        let completionEvents: HarnessEvent[] = [];
463	        const accept = (record: Record<string, unknown>): void => {
464	          // Native missing-session refusals can precede init (CLI 2.1.304). They are not
465	          // turn output. Await the fixed stderr refusal; never retain the provider error body.
466	          if (
467	            !initialized &&
468	            !accepted &&
469	            record.type === 'result' &&
470	            record.is_error === true &&
471	            record.num_turns === 0
472	          )
473	            return;
474	          const events = accumulator.push(record);
475	          if (events.some((event) => event.type === 'session')) initialized = true;
476	          if (events.some((event) => event.type === 'submitted')) accepted = true;
477	          if (record.type === 'result') {
478	            // A validated result proves consumption even while the CLI is still alive.
479	            // Persist that evidence now; usage/completion remain gated by process outcome.
480	            completionEvents = [];
481	            for (const event of events) {
482	              if (event.type === 'submitted') queue.push(event);
483	              else completionEvents.push(event);
484	            }
485	            return;
486	          }
487	          for (const event of events) {
488	            if (event.type === 'session') resolveId(event.sessionId);
489	            queue.push(event);
490	          }
491	        };
492	        const args = [
493	          ...policyArgs(policy),
494	          '--model',
495	          settings.model,
496	          '--effort',
497	          settings.effort,
498	          '--output-format',
499	          'stream-json',
500	          '--verbose',
501	          ...(resumeId ? ['--resume', resumeId] : []),
502	          ...(request.turn.outputSchema
503	            ? ['--json-schema', JSON.stringify(request.turn.outputSchema)]
504	            : []),
505	          '--input-format',
506	          'text',
507	          '--print',
508	        ];
509	        delivery = 'delivery-uncertain';
510	        const result = await this.runner(
511	          {
512	            binary: this.binary,
513	            args,
514	            cwd: request.workingDirectory,
515	            env: this.environment,
516	            stdin: request.turn.prompt,
517	            signal: controller.signal,
518	            timeoutMs: null,
519	            maxOutputBytes: this.options.maxOutputBytes ?? 4 * 1024 * 1024,
520	          },
521	          (chunk) => {
522	            for (const record of parser.push(chunk)) accept(record);
523	          },
524	        );
525	        if (result.spawnCode) delivery = 'definitely-not-submitted';
526	        // Refusal diagnostics must never conceal an unconfirmed process or a transport cutoff.
527	        if (
528	          result.terminationUnconfirmed ||
529	          result.aborted ||
530	          result.timedOut ||
531	          result.overflow ||
532	          result.outputFailed ||
533	          result.callbackError
534	        )
535	          checkOutcome(result, controller.signal, request.workingDirectory);
536	        if (!accepted && result.turnRejection) {
537	          delivery =
538	            result.turnRejection === 'session-missing'
539	              ? 'session-missing'
540	              : 'definitely-not-submitted';
541	          if (result.turnRejection === 'session-missing')
542	            throw new ClaudeHarnessError(
543	              'HARNESS_SESSION_MISSING',
544	              'The recorded Claude conversation was not found',
545	            );
546	          if (result.turnRejection === 'auth')
547	            throw new ClaudeHarnessError(
548	              'HARNESS_NOT_AUTHENTICATED',
549	              'Claude requires authentication before submitting this turn',
550	            );
551	        }
552	        checkOutcome(result, controller.signal, request.workingDirectory);
553	        for (const record of parser.finish()) accept(record);
554	        const completed = accumulator.finish();
555	        for (const event of completionEvents) queue.push(event);
556	        return completed;
557	      } catch (error) {
558	        const failure =
559	          error instanceof ClaudeHarnessError && error.code === 'HARNESS_TERMINATION_UNCONFIRMED'
560	            ? error
561	            : controller.signal.aborted
562	              ? abortError()
563	              : error instanceof ClaudeHarnessError
564	                ? error.code === 'HARNESS_PROTOCOL_ERROR' && detectedVersion !== undefined
565	                  ? new ClaudeHarnessError(
566	                      error.code,
567	                      `Claude CLI ${detectedVersion}: required capability stream-json protocol verification failed: ${error.message}`,
568	                      error.retriable,
569	                    )
570	                  : error.code === 'HARNESS_UNSUPPORTED_POLICY' && detectedVersion !== undefined
571	                    ? new ClaudeHarnessError(
572	                        error.code,
573	                        `Claude CLI ${detectedVersion}: required capability effective launch policy verification failed: ${error.message}`,
574	                        error.retriable,
575	                      )
576	                    : error
577	                : new ClaudeHarnessError('HARNESS_TURN_FAILED', 'Claude turn failed');
578	        rejectId(failure);
579	        if (failure instanceof ClaudeHarnessError)
580	          queue.push({
581	            type: 'error',
582	            code: failure.code,
583	            message: failure.message,
584	            retriable: failure.retriable,
585	            submission: delivery,
586	          });
587	        throw failure;
588	      } finally {
589	        closed = true;
590	        signal.removeEventListener('abort', abort);
591	        queue.close();
592	      }
593	    };
594	    const result = pump();
595	    result.catch(() => undefined);
596	    let cancellation: Promise<void> | undefined;
597	    return {
598	      sessionId,
599	      events: queue,
600	      result,
601	      cancel: () => {
602	        if (closed)
603	          return result.then(
604	            () => undefined,
605	            (error: unknown) => {
606	              if (
607	                error instanceof ClaudeHarnessError &&
608	                error.code === 'HARNESS_TERMINATION_UNCONFIRMED'
609	              )
610	                throw error;
611	            },
612	          );
613	        cancellation ??= (async () => {
614	          controller.abort();
615	          await result.catch((error: unknown) => {
616	            if (
617	              error instanceof ClaudeHarnessError &&
618	              error.code === 'HARNESS_TERMINATION_UNCONFIRMED'
619	            )
620	              throw error;
621	          });
622	        })();
623	        return cancellation;
624	      },
625	    };
626	  }
627	}
