  } catch (error) {
    actual = { error: error.code };
  }
  if (actual.sha256 !== file.sha256 || actual.bytes !== file.bytes)
    sourceMismatch.push({ path: file.relativePath, actual, expected: { bytes: file.bytes, sha256: file.sha256 } });
